// RentBillingSchema.js — FRONTEND schema: labels, formulas, remarks, click-throughs. Generated by gen-report.js from report.map (same folder).
// The numbers come from the backend twin app/api/digitenant/reports/rent/billing/list/RentBillingSchema.js (same measure keys).
import { getApiRoutes } from '../../../AppRoutes/apiRoutesHandler';
import RentBillingActions from './logicControl/actionsRegistry';
const apiRoutes = getApiRoutes();

export const RentBillingSchema = {
  entity: 'rental_rent_billing',
  label: 'Billed vs Collected',
  description: '',
  apiBase: apiRoutes.rentbilling?.base,
  moduleRole: 'view_reports',
  currency: 'KES',
  actionRegistry: RentBillingActions,

  groupBy: 'month',
  groupLabel: 'Month',
  groupByOptions: [{ key: 'month', label: 'Month' }, { key: 'year', label: 'Year' }],

  fields: [
    { key: 'invoices', label: 'Invoices Issued', from: 'rent_invoices' },
    { key: 'billed', label: 'Billed', from: 'rent_invoices.total_amount', type: 'money' },
    { key: 'collected', label: 'Collected', from: 'rent_invoices.paid_amount', type: 'money' },
    { key: 'outstanding', label: 'Outstanding', calc: 'billed - collected', type: 'money' },
    { key: 'rate', label: 'Collected %', calc: 'round(collected / billed * 100)' },
    { key: 'chg', label: 'Billed vs Previous', calc: 'change(billed)' },
  ],

  remarks: [
    { if: 'billed == 0', tone: 'neutral', title: 'Nothing billed', say: 'No invoices were issued in {label}.' },
    { if: 'rate !== null && rate < 70', tone: 'bad', title: 'Weak collection', say: 'Only {rate}% of the {billed} billed in {label} was collected, and {outstanding} is outstanding.' },
    { if: 'rate !== null && rate < 90', tone: 'watch', title: 'Gaps', say: '{rate}% of the {billed} billed in {label} was collected, with {outstanding} still outstanding.' },
    { if: 'true', tone: 'good', title: 'On track', say: '{rate}% of the {billed} billed in {label} was collected.' },
  ],

  headline: '{label}: {billed} billed, {rate}% collected, {outstanding} outstanding.',

  // coming periods the report page adds after the history (see forecast.js)
  forecast: [{ key: 'billed', next: 3, method: 'auto', integer: false }],
};
